contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: from, target contract address, dynamic tos array, value v
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        require(_tos.length > 0);
        // record balances before
        uint before_c_balance = address(c).balance;
        uint before_self_balance = address(this).balance;

        bool reverted;
        try c.transfer(from, caddress, _tos, v) returns (bool res) {
            reverted = false;
            // returned res should be true per implementation when not reverted
            // but we will observe it via assert together with balances
            // store res in a local variable visible to the assert by re-reading nothing (we only can use locals)
            // to include res in the final assertion, capture it into a local variable
            bool returnedTrue = res;
            uint after_c_balance = address(c).balance;
            uint after_self_balance = address(this).balance;
            // If call succeeded, contract returns true and balances should be unchanged
            assert(returnedTrue && after_c_balance == before_c_balance && after_self_balance == before_self_balance);
            return;
        } catch {
            reverted = true;
            // If it reverted, ensure balances unchanged as well (no Ether movement on revert)
            uint after_c_balance = address(c).balance;
            uint after_self_balance = address(this).balance;
            assert(reverted && after_c_balance == before_c_balance && after_self_balance == before_self_balance);
            return;
        }
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: from, target contract address, dynamic tos array, value v
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        require(_tos.length > 0);
        // record balances before
        uint before_c_balance = address(c).balance;
        uint before_self_balance = address(this).balance;

        bool callSucceeded = false;
        bool returnedValue = false;
        bool callReverted = false;

        // make the state-changing call as a top-level statement
        try c.transfer(from, caddress, _tos, v) returns (bool res) {
            callSucceeded = true;
            returnedValue = res;
        } catch {
            callReverted = true;
        }

        uint after_c_balance = address(c).balance;
        uint after_self_balance = address(this).balance;

        // Single general assert: either the call reverted, or it succeeded and returned true; in both cases balances unchanged
        assert((callReverted && after_c_balance == before_c_balance && after_self_balance == before_self_balance) || (callSucceeded && returnedValue && after_c_balance == before_c_balance && after_self_balance == before_self_balance));
    }

    receive() external payable { }
}

contract InvMutTest {
