    // single public test: ensure transfer never returns false when _tos.length > 0
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted = false;
        bool ret = false;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            ret = r;
        } catch {
            reverted = true;
        }

        // General rule: for any inputs with non-empty _tos, the call either reverts or returns true (never false)
        assert(reverted || ret == true);
    }

    receive() external payable { }
}

